// Update updates the modal.
func (m *ChoiceModal) Update(msg tea.Msg) (*ChoiceModal, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height

	case tea.KeyPressMsg:
		switch msg.String() {
		// ←/→ between buttons (Rule 135 — Tab is reserved for tabs). The
